/**
 * The line a parent's thread gets while its subtree is still open, and where it goes.
 *
 * It used to be a comment of its own, posted next to the report the child's closing
 * run had already left on the same thread: one completion, two comments, two
 * notifications for everyone watching. It is edited into the report now, which is
 * where a person looking for "what happened to #9" is already reading, and an edit
 * notifies nobody.
 *
 * Not a command: the report is `llm-context=include`, so a line beginning with `/`
 * would read to the parent's thread readers as somebody asking that node for an
 * agent, and an ask nothing claimed is exactly what makes the gate answer
 * `parent-busy` and take its marker back.
 */
export function subIssueProgressLine(child: number, remaining: number): string {
  return `Atomaton: Sub-task #${child} completed. ${remaining} sub-task(s) still in progress.`;
}

/**
 * `body` with the current progress line replaced by `line`.
 *
 * Replaced, not appended: the gate is idempotent only if a second run over the same
 * completion produces the same body, and the count it carries can differ between
 * those runs as siblings close. Recognised by the sentence's own opening — this
 * module writes that sentence (`subIssueProgressLine`), so the shape it strips is one
 * it wrote.
 */
export function withProgressLine(body: string, line: string): string {
  const kept = body.split("\n").filter((text) => !text.trimStart().startsWith(PROGRESS_OPENING));
  return `${kept.join("\n").replace(/\s+$/, "")}\n\n${line}`;
}
