/** Where a child's completion comment sits on its parent, when it is there yet. */
export interface SubIssueComment { id: string; body: string; }

/**
 * The report this child's closing run left on its parent, if any.
 *
 * Found by the `sub-result` tag AND the folded-report shape. The tag alone also
 * matches the bare progress comment this machinery posts on the paths where nobody
 * wrote a report; editing that one would put a report where a person-facing sentence
 * was, and the child's own run would still post its report after it — two comments
 * again, one of them rewritten into something nobody meant.
 *
 * `readProse`, and only on a non-human comment: this is GitHub's text, where a quoted
 * tag is a sample rather than a record, and a person retyping the shape in their own
 * words is their prose.
 */
export function findSubIssueReport(repo: string, parent: number, child: number): SubIssueComment | undefined {
  for (const comment of listComments(repo, parent)) {
    const body = comment.body ?? "";
    if (isHumanActor(comment.user?.type)) continue;
    if (SUB_RESULT_TAG.readProse(body) !== child) continue;
    if (!body.includes(REPORT_FOLD)) continue;
    return { id: String(comment.id), body };
  }
  return undefined;
}
